CREATE TABLE "attachments" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"ticket_id" BIGINT NOT NULL,"uploader_id" UUID NOT NULL,"storage_key" VARCHAR(255) NOT NULL,"original_name" VARCHAR(255) NOT NULL,"mime" VARCHAR(80) NOT NULL,"size" INTEGER NOT NULL,"created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "attachments_pkey" PRIMARY KEY("id"),CONSTRAINT "attachments_storage_key_key" UNIQUE("storage_key"),CONSTRAINT "attachments_ticket_fkey" FOREIGN KEY("ticket_id") REFERENCES "tickets"("id") ON DELETE CASCADE,CONSTRAINT "attachments_size_check" CHECK("size">0 AND "size"<=5242880));
CREATE INDEX "attachments_ticket_id_created_at_idx" ON "attachments"("ticket_id","created_at");
ALTER TABLE "notifications" ADD COLUMN "delivery_attempts" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "next_attempt_at" TIMESTAMPTZ(3), ADD COLUMN "delivery_error" VARCHAR(255);
